function applyRemoteReplaceState(env) {
        try {
            if (typeof userWriteInFlight === 'function' && userWriteInFlight()) {
                try { dbgLog('对账', { action: '发送/提取在途 → 整体替换降级为并集合并（避免覆盖刚提取的记忆）' }); } catch (e) { }
                const r = applyRemoteMergeToState(env);
                if (r) return 'merge';
                try { dbgLog('对账', { action: '并集合并失败 → 放弃本次整体替换（保留本端）' }); } catch (e) { }
                try { warn('发送/提取进行中：本次「整体采用对端」已放弃（避免覆盖刚提取的记忆）', ''); } catch (e) { }
                return null;
            }
        } catch (e) { }
        return adoptRemoteEnvelope(env);
    }

