case 'syncPickRemote': {
                    const pend = crossPendingGet();
                    crossPendingClear();
                    (async () => {
                        try {
                            const ok = pend ? applyRemoteReplaceState(pend.env) : false;
                            await storageWriteAll(storageEnvelope(state));
                            // 分歧处置留痕
                            try {
                                const st = syncLogStat(state);
                                if (typeof crossSyncLogPush === 'function') crossSyncLogPush({ action: '分歧选择', mode: ok ? '采用对端(整体替换)' : '未找到待选对端', changed: !!ok, localN: st.n, localBytes: st.bytes, remoteN: st.n, remoteBytes: st.bytes, afterN: st.n, afterBytes: st.bytes, localHash: dataAggHash(state), remoteHash: ok ? dataAggHash(state) : '', afterHash: dataAggHash(state), note: ok ? '用户选择采用对端版本，本端已替换为对端数据' : '待选对端缺失，未改动' });
